#!/bin/bash
# The 10-30 valve safety fixes + report items 6/7/9, flown in Isaac (2026-10-30 night, user: "yes").
# Harness as archive/wb_valve_turning_flight_20261028/sim/chain_q3.sh: v2 valve at 0.072 N.m (drive model),
# the shipped valve yaml (regenerated by try_valve.sh from the generator), raw mocap, headless, the ARM GS
# flying Ready / Turn / Exit by itself (--gs-auto, as on hardware), each run stopped 4 s after the exit.
#   setsid nohup bash chain.sh > chain.out 2>&1 &      (touch runs/STOP to skip the rest)
C=~/fsc_PegasusSimulator/docs/docs_aerial_manipulator/archive/valve_turning_20261015
HERE="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
R="$HERE/runs"; mkdir -p "$R"
export PL_RUNS_DIR="$R"
export PEGASUS_VALVE_USD=~/fsc_PegasusSimulator/extensions/fsc_aerial_manipulation/fsc_aerial_manipulation/rotorcraft/assets/Valve_Assembly_v2.usda
export PEGASUS_VALVE_FRICTION=0.072 PEGASUS_VALVE_FRICTION_MODEL=drive PEGASUS_VALVE_DAMPING=0.0
DRV=~/fsc_PegasusSimulator/docs/docs_aerial_manipulator/archive/wb_valve_turning_flight_20261028/tools/driver
clean() { ~/ros2_ws/src/fsc_autopilot_ros2/scripts/isaacsim/stop_isaacsim_stack.sh > /dev/null 2>&1; ~/fsc_PegasusSimulator/scripts/kill_stale_sim_processes.sh -y > /dev/null 2>&1; sleep 5; }
fly() { tag=$1; shift
  echo "$(date +%H:%M:%S) start $tag $* ${EXTRA:-}"
  ARM_GS_AUTO_STEPS=true ARM_GS_AUTO_EXIT_DELAY=0.2 RELEASE_AT_OPEN=0 \
    PL_PUSH_TOOLS="$DRV" PL_DRIVER_ARGS="--gs-auto --stop-after-exit --stop-hold 4 ${EXTRA:-}" bash $C/tools/try_valve.sh "$tag" "$@"; }
gs() { [[ -e "$R/STOP" ]] && { echo "STOP file: skipping $1"; return; }; clean; fly "$@"; }

# 1. nominal: the mission end to end with items 6 (open at Go To Start, heading gate) and 9 (heading follows)
unset PEGASUS_PLANT_FORCE_NOISE
for k in 1 2 3; do gs vs_nom_$k; done
# 2. the hardware-like drift (0.32 N @ 0.12 Hz): where the free-axis heading should matter
for k in 2 3 4; do export PEGASUS_PLANT_FORCE_NOISE="0.32,0.12,$k"; gs vs_hw_s$k; done
# 3. item 2: an arm-guard abort in the turn (the q3 floor raised to 25 deg so it trips): the claw must follow
#    the vehicle at once (no world-held release)
unset PEGASUS_PLANT_FORCE_NOISE
gs vs_q3trip push_pull_guard_q3_min_deg=25.0
# 4. item 1 + 2: the sway guard tripped in contact (0.05 m/s on drift seed 2)
export PEGASUS_PLANT_FORCE_NOISE="0.32,0.12,2"
gs vs_swaytrip push_pull_guard_sway_speed=0.05
# 5. item 3: SAFETY in contact with the node's arm hold OFF (the hardware setting): the RELEASE, not 0.3 s of
#    the law's last torque. The node is switched out of DIRECT 5 s into the turn by force_safety.py.
unset PEGASUS_PLANT_FORCE_NOISE
if [[ ! -e "$R/STOP" ]]; then
  clean
  ( source /opt/ros/humble/setup.bash; source ~/ros2_ws/install/setup.bash
    export FASTRTPS_DEFAULT_PROFILES_FILE=~/fsc_PegasusSimulator/docs/docs_aerial_manipulator/archive/q2_sine_sim_20260924/tools/fastdds_udp_only.xml
    setsid nohup /usr/bin/python3 "$HERE/force_safety.py" 5.0 "$R/vs_safety.force.log" > /dev/null 2>&1 & )
  fly vs_safety wb_arm_hold_stream=false
fi
# 6. the drone's mocap frozen 2.5 s, 4 s into the turn (the guard chain with the new jump gate)
EXTRA="--mocap-fault freeze@push+4:2.5" gs vs_mfreeze
clean
echo "$(date +%H:%M:%S) CHAIN DONE"
